"""Exploration: per-token activation of L12/N5397 for texts.
Input: .json (list of strings) or .txt (one per line, literal \\n -> newline, ## comments)."""
import sys, json, torch
from bonsai_interp.model import load, StopForward
from bonsai_interp.probe.textinv import PREAMBLES
PM, NM = 2.109375, 5.25
model, tok, rec = load("bonsai1")
pre = PREAMBLES[0]; k = len(tok(pre).input_ids)


@torch.no_grad()
def acts(t):
    ids = tok(pre + t, return_tensors="pt").input_ids.cuda()
    rec.mode, rec.layers, rec.stop_at = "act", {12}, 12
    try:
        model.model(input_ids=ids)
    except StopForward:
        pass
    finally:
        rec.mode, rec.stop_at = None, None
    a = rec.store.pop(12)[0, :, 5397].float().cpu().numpy(); rec.clear()
    return [tok.decode([i]) for i in ids[0, k:]], a[k:]


def lines(fn):
    if fn.endswith(".json"):
        return json.load(open(fn, encoding="utf-8"))
    return [l.rstrip("\n").replace("\\n", "\n") for l in open(fn, encoding="utf-8")
            if l.strip() and not l.startswith("##")]


for fn in sys.argv[1:]:
    for t in lines(fn):
        ts, a = acts(t)
        mx, mn = a.max() / PM, -a.min() / NM
        s = "".join((f"[{x}|{v/PM:+.2f}]" if v / PM > 0.2 else (f"{{{x}|{-v/NM:.2f}}}" if -v / NM > 0.2 else x))
                    for x, v in zip(ts, a))
        print(f"+{mx:.2f} -{mn:.2f} :: {s}".replace("\n", "⏎"))

